  function findSimilarTracks(track,limit=24){if(!track)return[];const tags=new Set((track.customTags||[]).map(x=>String(x).toLowerCase()));const words=String(track.title||'').toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>2);return state.library.filter(t=>favKey(t)!==favKey(track)).map(t=>{let score=0;if(normArtist(t.artist)===normArtist(track.artist)&&track.artist!=='Unknown Artist')score+=5;if(String(t.album||'').toLowerCase()===String(track.album||'').toLowerCase()&&track.album!=='Unknown Album')score+=3;if(track.genre&&t.genre&&String(t.genre).toLowerCase()===String(track.genre).toLowerCase())score+=3;const otherTags=new Set((t.customTags||[]).map(x=>String(x).toLowerCase()));for(const tag of tags)if(otherTags.has(tag))score+=2;const other=String(t.title||'').toLowerCase();for(const w of words)if(other.includes(w))score+=.5;if(isFav(t))score+=.25;return {track:t,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.track);}
  function showSimilarTracks(track=state.current){if(!track){toast('Choose a track first.','error');return;}const similar=findSimilarTracks(track);if(!similar.length){toast('No similar local tracks found. Add artist, genre, or custom tags to improve matching.','');return;}modal('Similar tracks',`<p class="modal-copy">Matches are ranked using local artist, album, genre, title and custom-tag similarity.</p><div class="similar-track-list">${similar.map(t=>`<button class="similar-track-item" data-similar-path="${esc(t.relativePath)}"><strong>${esc(t.title)}</strong><span>${esc(t.artist)} · ${esc(t.album)}</span></button>`).join('')}</div>`,[{label:'CLOSE',onClick:closeModal},{label:'ADD ALL TO QUEUE',className:'primary-button',onClick:()=>{closeModal();addTracksToQueue(similar);}}]);$('modal-body').querySelectorAll('[data-similar-path]').forEach(b=>b.addEventListener('click',()=>{const t=findTrack(b.dataset.similarPath);closeModal();if(t)playList([t],0,true);}));}
  function openAlbumMode(){const t=state.current;if(!t){toast('Start a track from an album first.','error');return;}const albumTracks=state.library.filter(x=>String(x.album||'').toLowerCase()===String(t.album||'').toLowerCase()&&String(x.artist||'').toLowerCase()===String(t.artist||'').toLowerCase()).sort((a,b)=>(a.trackNumber||999)-(b.trackNumber||999)||a.relativePath.localeCompare(b.relativePath,undefined,{numeric:true,sensitivity:'base'}));if(!albumTracks.length){toast('No other local tracks were found for this album.','');return;}const cover=trackArtworkUrl(t,true);modal('Album mode',`<div class="album-mode-hero">${cover?`<img src="${cover}" alt="Album cover">`:'<div class="album-mode-placeholder">◖</div>'}<div><span class="eyebrow">ALBUM PLAYBACK</span><h3>${esc(t.album||'Unknown Album')}</h3><p>${esc(t.artist||'Unknown Artist')} · ${albumTracks.length} tracks${t.year?' · '+esc(t.year):''}</p></div></div><div class="album-mode-list">${albumTracks.map((x,i)=>`<button data-album-track="${esc(x.relativePath)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(x.title)}</strong><small>${fmtTime(x.duration)}</small></button>`).join('')}</div>`,[{label:'CLOSE',onClick:closeModal},{label:'PLAY ALBUM',className:'primary-button',onClick:()=>{closeModal();playList(albumTracks,Math.max(0,albumTracks.findIndex(x=>favKey(x)===favKey(t))),true);}}]);$('modal-body').querySelectorAll('[data-album-track]').forEach(b=>b.addEventListener('click',()=>{const picked=findTrack(b.dataset.albumTrack);closeModal();if(picked)playList(albumTracks,Math.max(0,albumTracks.findIndex(x=>favKey(x)===favKey(picked))),true);}));}
  function toggleFavorite(track){if(!track)return;const k=favKey(track);if(state.favorites.has(k))state.favorites.delete(k);else state.favorites.add(k);saveJSON('favorites',[...state.favorites]);renderCounts();renderCurrent();renderTableViews();toast(state.favorites.has(k)?'Added to Favorites.':'Removed from Favorites.');}
  function orderedTracks(list,firstTrack=null){const arr=[...list];const max=Math.max(1,...arr.map(t=>state.plays[favKey(t)]||0));const keyed=arr.map(t=>{let wt=1+(isFav(t)?1.2:0)+1.5*(1-(state.plays[favKey(t)]||0)/max);return {t,k:Math.pow(Math.random(),1/wt)};}).sort((a,b)=>b.k-a.k).map(x=>x.t);for(let i=1;i<keyed.length;i++){if(normArtist(keyed[i].artist)===normArtist(keyed[i-1].artist)){for(let j=i+1;j<Math.min(keyed.length,i+8);j++){if(normArtist(keyed[j].artist)!==normArtist(keyed[i-1].artist)){[keyed[i],keyed[j]]=[keyed[j],keyed[i]];break;}}}}if(firstTrack){const i=keyed.findIndex(t=>t===firstTrack);if(i>0){const [x]=keyed.splice(i,1);keyed.unshift(x);}}return keyed;}
