    clearCrossfade();const old=state.activeDeck;const target=1-old;const standby=state.decks[target];const current=state.decks[old];try{current.audio.pause();standby.audio.pause();state.decks.forEach(d=>{d.gain.gain.cancelScheduledValues(state.audioCtx.currentTime);d.gain.gain.setValueAtTime(0,state.audioCtx.currentTime);d.mix=0;});}catch{}
