  function showTrackInfo(track){if(!track)return;const modified=track.lastModified?new Date(track.lastModified).toLocaleString():'Unknown';const details=[['TITLE',track.title||track.fileName],['ARTIST',track.artist||'Unknown Artist'],['ALBUM',track.album||'Unknown Album'],['GENRE',track.genre||'Unknown'],['YEAR',track.year||'Unknown'],['RATING',track.rating?`${track.rating}/5`:'UNRATED'],['CUSTOM TAGS',(track.customTags||[]).join(', ')||'NONE'],['REPLAYGAIN',Number.isFinite(track.replayGainDb)?`${track.replayGainDb} dB`:'NOT IN ID3 TAGS'],['FILE',track.fileName],['LOCATION',track.relativePath],['FORMAT',fileExt(track.fileName).toUpperCase()],['SIZE',`${(track.size/1048576).toFixed(2)} MB`],['DURATION',fmtTime(track.duration)],['LAST MODIFIED',modified],['COUNTED PLAYS',String(state.plays[favKey(track)]||0)],['FAVORITE',isFav(track)?'YES':'NO']];modal('Track information',`<div class="track-info-grid">${details.map(([k,v])=>`<div><span>${esc(k)}</span><strong title="${esc(v)}">${esc(v)}</strong></div>`).join('')}</div>`,[{label:'CLOSE',onClick:closeModal},{label:'PLAY TRACK',className:'primary-button',onClick:()=>{closeModal();playList([track],0,true);}}]);}

