  function commandIcon(key){return ({play:'▶',next:'▶|',previous:'|◀',shuffle:'⤨',mix:'✧',visualizer:'∿',theme:'◐',disco:'✳',studio:'▦',void:'◉',deck:'▭',record:'◍',profiles:'◈',moments:'✦',guide:'?',folder:'▣',compat:'⇧',lyrics:'♫',eq:'≋',collections:'✧',statistics:'▥',search:'⌕',queue:'☷',playlist:'▣','playlist-add':'＋'})[key]||'⌘';}
