  function saveVisualizerProfile(){state.vizProfiles=state.vizProfiles||{};state.vizProfiles[state.vizMode]={sensitivity:state.sensitivity,glow:state.vizGlow,smoothing:state.vizSmoothing,quality:state.vizQuality};}
