  async function findDuplicateTracks(){
    if(!state.library.length){toast('Connect a music folder first.','error');return;}
    modal('Duplicate finder',`<div class="scan-progress"><strong>Preparing file fingerprints…</strong><span id="duplicate-progress">0 / ${state.library.length}</span><div class="scan-progress-track"><i id="duplicate-progress-fill"></i></div><p class="setting-note">Same-size candidates are fingerprinted. Files over 80 MB use first/last chunk hashes to keep memory use bounded; verify matches before removing anything.</p></div>`,[{label:'CANCEL / CLOSE',onClick:closeModal}]);
    const bySize=new Map();for(const t of state.library){if(!bySize.has(t.size))bySize.set(t.size,[]);bySize.get(t.size).push(t);}const candidates=[...bySize.values()].filter(g=>g.length>1).flat();if(!candidates.length){modal('Duplicate finder','<p class="modal-copy">No same-size candidates were found.</p>',[{label:'CLOSE',onClick:closeModal}]);return;}
    const hashes=new Map();let done=0;for(const t of candidates){try{const fp=await fingerprintTrack(t);if(!hashes.has(fp))hashes.set(fp,[]);hashes.get(fp).push(t);}catch{}done++;if(done%5===0||done===candidates.length){const lab=$('duplicate-progress'),fill=$('duplicate-progress-fill');if(lab)lab.textContent=`${done} / ${candidates.length} candidates`;if(fill)fill.style.width=(done/candidates.length*100)+'%';await new Promise(r=>setTimeout(r,0));}}
    const groups=[...hashes.values()].filter(g=>g.length>1);if(!groups.length){modal('Duplicate finder',`<p class="modal-copy">No duplicate fingerprint matches were found among ${candidates.length} same-size candidates.</p><p class="setting-note">No files were changed or deleted.</p>`,[{label:'CLOSE',onClick:closeModal}]);return;}
    modal('Possible duplicate files',`<p class="modal-copy">${groups.length} duplicate group${groups.length===1?'':'s'} found. BLACKBOX has not deleted or modified any audio files.</p><div class="duplicate-groups">${groups.map((g,gi)=>`<section class="duplicate-group"><strong>GROUP ${gi+1} · ${(g[0].size/1048576).toFixed(2)} MB</strong>${g.map(t=>`<button class="similar-track-item" data-duplicate-path="${esc(t.relativePath)}"><strong>${esc(t.title||t.fileName)}</strong><span>${esc(t.relativePath)}</span></button>`).join('')}</section>`).join('')}</div>`,[{label:'CLOSE',onClick:closeModal}]);$('modal-body').querySelectorAll('[data-duplicate-path]').forEach(b=>b.addEventListener('click',()=>{const t=findTrack(b.dataset.duplicatePath);closeModal();if(t)rowMenu(t);}));
  }
  async function scanMissingArtwork(){
    if(!state.library.length){toast('Connect a music folder first.','error');return;}modal('Artwork scan',`<div class="scan-progress"><strong>Checking embedded artwork…</strong><span id="art-scan-progress">0 / ${state.library.length}</span><div class="scan-progress-track"><i id="art-scan-progress-fill"></i></div></div>`,[{label:'CLOSE',onClick:closeModal}]);let done=0;const missing=[];
    for(const t of state.library){try{await loadCustomArtwork(t);if(!t.artworkBlob){let file=t.file;if(!file&&t.handle)file=await t.handle.getFile();if(file)await readTags(t,file,true);applyTrackOverrides(t);}if(!t.artworkBlob)missing.push(t);}catch{if(!t.artworkBlob)missing.push(t);}done++;if(done%8===0||done===state.library.length){const lab=$('art-scan-progress'),fill=$('art-scan-progress-fill');if(lab)lab.textContent=`${done} / ${state.library.length}`;if(fill)fill.style.width=(done/state.library.length*100)+'%';await new Promise(r=>setTimeout(r,0));}}
    modal('Artwork scan complete',`<p class="modal-copy">${state.library.length-missing.length} track(s) have embedded or custom covers. ${missing.length} track(s) appear to be missing artwork.</p><p class="setting-note">Attach artwork locally using a track’s menu → Edit metadata, tags & cover. BLACKBOX does not modify the original audio file.</p><div class="similar-track-list">${missing.slice(0,80).map(t=>`<button class="similar-track-item" data-missing-art-path="${esc(t.relativePath)}"><strong>${esc(t.title||t.fileName)}</strong><span>${esc(t.artist)} · ${esc(t.relativePath)}</span></button>`).join('')||'<div class="small-empty">No missing artwork detected.</div>'}</div>${missing.length>80?`<p class="setting-note">Showing first 80 of ${missing.length} tracks.</p>`:''}`,[{label:'CLOSE',onClick:closeModal}]);$('modal-body').querySelectorAll('[data-missing-art-path]').forEach(b=>b.addEventListener('click',()=>{const t=findTrack(b.dataset.missingArtPath);closeModal();if(t)editTrackMetadata(t);}));renderAll();
  }
