  async function exportFullBackup(){const buttons=[$('export-data'),$('settings-export-full')].filter(Boolean);try{buttons.forEach(b=>{b.disabled=true;b.dataset.oldLabel=b.textContent;b.textContent='PREPARING BACKUP…';});const backup=await collectFullBackup();const payload=new TextEncoder().encode(JSON.stringify(backup));const zip=zipStored([{name:'BLACKBOX-BACKUP.json',data:payload}]);downloadBlob('BLACKBOX-Backup-'+new Date().toISOString().slice(0,10)+'.zip',new Blob([zip],{type:'application/zip'}));toast(`Complete BLACKBOX backup exported${Object.keys(backup.customArtwork||{}).length?` with ${Object.keys(backup.customArtwork).length} custom cover(s)`:''}. Music audio files are not included.`,'success');}catch(e){toast(`Backup export failed: ${e.message||e}`,'error');}finally{buttons.forEach(b=>{b.disabled=false;b.textContent=b.dataset.oldLabel||'EXPORT EVERYTHING ZIP';delete b.dataset.oldLabel;});}}
  async function chooseBackupMode(){return new Promise(resolve=>{modal('Import BLACKBOX backup','<p class="modal-copy">Choose how to use this backup. Restore replaces the app data; Merge combines compatible records and leaves current settings in place.</p>',[{label:'CANCEL',onClick:()=>{closeModal();resolve('cancel');}},{label:'MERGE DATA',onClick:()=>{closeModal();resolve('merge');}},{label:'RESTORE EVERYTHING',className:'primary-button',onClick:()=>{closeModal();resolve('restore');}}]);});}
