  async function importFullData(file){try{let text='';if(/\.zip$/i.test(file.name)||((await file.slice(0,2).arrayBuffer()).byteLength===2&&new TextDecoder().decode(await file.slice(0,2).arrayBuffer())==='PK')){const bytes=await file.arrayBuffer();const found=await readZipEntry(bytes,'BLACKBOX-BACKUP.json');if(!found)throw new Error('This ZIP does not contain BLACKBOX-BACKUP.json. Use EXPORT EVERYTHING ZIP from BLACKBOX.');text=new TextDecoder().decode(found);}else text=await file.text();const data=JSON.parse(text);if(!data||typeof data!=='object'||(!data.format&&!(data.favorites||data.playlists||data.settings)))throw new Error('This does not look like a BLACKBOX backup.');const mode=await chooseBackupMode();if(mode==='cancel')return;await applyBackupData(data,mode==='merge');}catch(e){toast(`Backup import failed: ${e.message||e}`,'error');}}
