  function showRecordArtworkTransition(track,duration=1.5){if(!track||!$('record-next-label-art'))return;clearTimeout(state.recordTransitionTimer);const art=trackArtworkUrl(track,true);state.recordPendingArtworkKey=favKey(track);setImageSource($('record-next-label-art'),art);$('record-next-label-art').classList.toggle('active',!!art);$('record-transition-label').textContent=duration>0?'BLENDING ARTWORK':'ARTWORK READY';const light=$('record-workspace');if(light){light.style.setProperty('--record-transition-duration',`${Math.max(.25,duration)}s`);light.classList.add('record-transitioning');}state.recordTransitionTimer=setTimeout(()=>{state.recordTransitionTimer=0;const current=state.current;const currentKey=current?favKey(current):'';if(currentKey===state.recordPendingArtworkKey){setImageSource($('record-label-art'),trackArtworkUrl(current,true));state.recordArtworkKey=currentKey;setImageSource($('record-next-label-art'),'');$('record-next-label-art').classList.remove('active');$('record-transition-label').textContent='ARTWORK LOCKED';}state.recordPendingArtworkKey='';light?.classList.remove('record-transitioning');renderRecordWorkspace();},Math.max(.25,duration)*1000+120);}
