  function handleGlobalKey(e){if(state.experience==='void')revealVoidControls();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('command-scrim').classList.contains('hidden'))openCommandPalette();else closeCommandPalette();return;}const tag=e.target?.tagName?.toLowerCase();const editing=['input','textarea','select'].includes(tag)||e.target?.isContentEditable;if(editing){if(e.key==='Escape'&&e.target.id==='global-search'){$('global-search').value='';renderTableViews();}return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key===' '){e.preventDefault();playPause();return;}const k=e.key.toLowerCase();switch(k){case'n':nextTrack();break;case'b':previousTrack();break;case'arrowleft':e.preventDefault();if(activeDeck())activeDeck().audio.currentTime=Math.max(0,activeDeck().audio.currentTime-state.seekSeconds);break;case'arrowright':e.preventDefault();if(activeDeck()&&Number.isFinite(activeDeck().audio.duration))activeDeck().audio.currentTime=Math.min(activeDeck().audio.duration,activeDeck().audio.currentTime+state.seekSeconds);break;case'arrowup':e.preventDefault();setVolume(state.volume+5);break;case'arrowdown':e.preventDefault();setVolume(state.volume-5);break;case'[':stepSpeed(-1);break;case']':stepSpeed(1);break;case'm':toggleMute();break;case's':setShuffle();break;case'r':setRepeat(state.repeat+1);break;case'f':toggleFavorite(state.current);break;case't':toggleSleep();break;case'1':cycleViz(0);break;case'2':cycleViz(1);break;case'3':cycleViz(2);break;case'4':cycleViz(3);break;case'5':cycleViz(4);break;case'6':cycleViz(5);break;case'v':cycleViz(state.vizMode+1);break;case'c':nextTheme();break;case'x':nextVariant();break;case'd':toggleDisco();break;case'e':nextDiscoStyle();break;case'y':cycleLayout();break;case'a':toggleAB();break;case'k':syncDelay(-25);break;case'l':syncDelay(25);break;case'h':if(state.view==='now')manualHit();else updateView('recent');break;case',':setSensitivity(state.sensitivity-3);break;case'.':setSensitivity(state.sensitivity+3);break;case'w':setCrossfade([0,2,4,6,8][([0,2,4,6,8].indexOf(state.crossfade)+1)%5]);toast(`Crossfade: ${state.crossfade}s`);break;case'g':fetchLyrics();updateView('now');break;case'p':if(state.current)choosePlaylistForTrack(state.current);else toast('Select a track first.');break;case'tab':e.preventDefault();updateView(state.view==='queue'?'now':'queue');break;case'escape':case'q':updateView('library');break;case'/':e.preventDefault();updateView('search');$('global-search').focus();break;}}
